"use server";

import { GAME_FAMILIES } from "./games";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireAdmin } from "./auth";

/** Game families whose OsTemplate rows are managed on the Game servers panel. */

const schema = z.object({
  id: z.string().min(1),
  minRamMB: z.coerce.number().int().min(256).max(262144),
  minDiskGB: z.coerce.number().int().min(1).max(4096),
  setupScript: z.string().max(20000).optional(),
});

/**
 * Save a game image (OsTemplate) — RAM/disk minimums, setup script and active
 * flag. ADMIN-only, audit-logged. Only operates on APPLICATION-category rows in
 * a known game family, so it can't be pointed at OS templates.
 */
export async function saveGameImage(
  prev: { ok?: boolean; error?: string } | undefined,
  formData: FormData,
): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireAdmin();

  const parsed = schema.safeParse({
    id: formData.get("id"),
    minRamMB: formData.get("minRamMB"),
    minDiskGB: formData.get("minDiskGB"),
    setupScript: formData.get("setupScript") ?? "",
  });
  if (!parsed.success) return { error: "Check the RAM/disk values — RAM ≥ 256 MB, disk ≥ 1 GB." };

  const active = formData.get("active") === "on";
  const { id, minRamMB, minDiskGB } = parsed.data;
  const setupScript = (parsed.data.setupScript ?? "").trim();

  const image = await db.osTemplate.findUnique({ where: { id } });
  if (!image) return { error: "Image not found." };
  if (image.category !== "APPLICATION" || !GAME_FAMILIES.includes(image.family as import("./games").GameFamily)) {
    return { error: "This image is not a managed game image." };
  }

  await db.osTemplate.update({
    where: { id },
    data: { minRamMB, minDiskGB, active, setupScript: setupScript || null },
  });
  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "games.saveImage",
      detail: `${image.name} (${image.family}): ${minRamMB}MB / ${minDiskGB}GB, active=${active}`,
    },
  });

  revalidatePath("/admin/games");
  return { ok: true };
}
