"use server";

// Server actions for the "Build with Claude AI" feature.
// Only async functions are exported (Next.js "use server" constraint).
//
// Flow: submitBuild -> (worker plans) -> AWAITING_APPROVAL
//       -> approveBuild (owner) -> (worker executes) -> DONE/FAILED
//       -> rejectBuild (owner) -> FAILED. Nothing runs on the server until the
//       owner approves the proposed command plan.

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { effectiveKeyFor } from "./anthropic";
import { serverRootPassword } from "./sftp";
import { getSettingBool } from "./settings";

const MAX_PROMPT_CHARS = 2000;
const MIN_PROMPT_CHARS = 8;
// Cap how many builds a user may have in flight, and how many they can start in
// a short window, to keep API + SSH usage sane.
const MAX_ACTIVE_BUILDS_PER_USER = 3;
const RATE_WINDOW_MS = 60_000;
const MAX_BUILDS_PER_WINDOW = 5;

// Statuses that mean a build is not yet finished (planning, awaiting approval,
// queued, or executing) — used for in-flight accounting.
const ACTIVE_STATUSES = ["QUEUED", "PLANNING", "AWAITING_APPROVAL", "RUNNING"] as const;

export async function submitBuild(
  serverId: string,
  prompt: string
): Promise<{ error?: string; buildId?: string }> {
  const user = await requireUser();

  // Feature flag: "Build with Claude" can be switched off platform-wide.
  if (!(await getSettingBool("feature_claude_builder", true))) {
    return { error: "Build with Claude is currently unavailable." };
  }

  const clean = (prompt ?? "").trim();
  if (clean.length < MIN_PROMPT_CHARS) {
    return { error: "Please describe what you'd like Claude to build (a sentence or two)." };
  }
  if (clean.length > MAX_PROMPT_CHARS) {
    return { error: `Prompt is too long (max ${MAX_PROMPT_CHARS} characters).` };
  }

  // BYOK gate: the owner must have an effective key (their own, or a platform fallback).
  const owner = await db.user.findUnique({
    where: { id: user.id },
    select: { anthropicKeyEnc: true },
  });
  if (!effectiveKeyFor(owner)) {
    return { error: "Add your Anthropic API key in Settings to use Build with AI." };
  }

  // Ownership: the server must belong to this user.
  const server = await db.server.findFirst({ where: { id: serverId, userId: user.id } });
  if (!server) return { error: "Server not found." };
  if (server.status !== "RUNNING") {
    return { error: "The server must be running to build on it." };
  }
  if (!server.ipAddress || !serverRootPassword(server)) {
    return { error: "This server isn't reachable yet — try again once it finishes provisioning." };
  }

  // Rate sanity.
  const active = await db.claudeBuild.count({
    where: { userId: user.id, status: { in: [...ACTIVE_STATUSES] } },
  });
  if (active >= MAX_ACTIVE_BUILDS_PER_USER) {
    return { error: "You already have builds in progress. Wait for them to finish before starting another." };
  }
  const recent = await db.claudeBuild.count({
    where: { userId: user.id, createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) } },
  });
  if (recent >= MAX_BUILDS_PER_WINDOW) {
    return { error: "Too many builds started just now — please wait a minute and try again." };
  }
  // One in-flight build per server keeps the SSH session serialized.
  const serverBusy = await db.claudeBuild.count({
    where: { serverId, status: { in: [...ACTIVE_STATUSES] } },
  });
  if (serverBusy > 0) {
    return { error: "A build is already in progress on this server." };
  }

  const build = await db.claudeBuild.create({
    data: { userId: user.id, serverId, prompt: clean, status: "QUEUED", approved: false },
  });

  // Enqueue the worker job; the handler reads the build via payload.buildId.
  // Because approved=false, the worker will PLAN (not execute).
  await db.job.create({
    data: { type: "CLAUDE_BUILD", serverId, payload: { buildId: build.id } },
  });

  await db.auditLog
    .create({
      data: { userId: user.id, action: "server.claude_build", detail: `${serverId} ${build.id}` },
    })
    .catch(() => {});

  revalidatePath("/dashboard/build");
  return { buildId: build.id };
}

/**
 * Owner approves the proposed plan. Marks it approved and enqueues a second
 * CLAUDE_BUILD job; the worker then executes the stored plan over SSH.
 */
export async function approveBuild(id: string): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();

  const build = await db.claudeBuild.findFirst({ where: { id, userId: user.id } });
  if (!build) return { error: "Build not found." };
  if (build.status !== "AWAITING_APPROVAL") {
    return { error: "This build isn't awaiting approval." };
  }
  if (!build.plan) {
    return { error: "This build has no plan to approve." };
  }

  await db.claudeBuild.update({
    where: { id },
    data: { approved: true, status: "QUEUED" },
  });

  await db.job.create({
    data: { type: "CLAUDE_BUILD", serverId: build.serverId, payload: { buildId: build.id } },
  });

  await db.auditLog
    .create({
      data: { userId: user.id, action: "server.claude_build_approve", detail: `${build.serverId} ${id}` },
    })
    .catch(() => {});

  revalidatePath("/dashboard/build");
  return { ok: true };
}

/** Owner rejects the proposed plan. Marks the build FAILED; nothing runs. */
export async function rejectBuild(id: string): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();

  const build = await db.claudeBuild.findFirst({ where: { id, userId: user.id } });
  if (!build) return { error: "Build not found." };
  if (build.status !== "AWAITING_APPROVAL") {
    return { error: "This build isn't awaiting approval." };
  }

  await db.claudeBuild.update({
    where: { id },
    data: { status: "FAILED", log: (build.log ?? "") + "\n[nxeon] Plan rejected by owner — nothing was run.\n" },
  });

  await db.auditLog
    .create({
      data: { userId: user.id, action: "server.claude_build_reject", detail: `${build.serverId} ${id}` },
    })
    .catch(() => {});

  revalidatePath("/dashboard/build");
  return { ok: true };
}

export async function listBuilds(serverId?: string) {
  const user = await requireUser();
  return db.claudeBuild.findMany({
    where: { userId: user.id, ...(serverId ? { serverId } : {}) },
    orderBy: { createdAt: "desc" },
    take: 20,
    include: { server: { select: { hostname: true } } },
  });
}

