// ---------------------------------------------------------------------------
// Flags / move / delete
// ---------------------------------------------------------------------------

/** Set or clear the \Seen or \Flagged flag on a message. */
export async function setFlag(
  folder: string,
  uid: number,
  flag: "seen" | "flagged",
  value: boolean,
  mailboxAddress?: string,
): Promise<void> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  enforceRateLimit(`mail:flag:${user.id}`, { max: 240, windowMs: 60 * 1000 });
  const imapFlag = flag === "seen" ? "\\Seen" : "\\Flagged";
  await withMailbox(cred, folder, async (client) => {
    if (value) await client.messageFlagsAdd(String(uid), [imapFlag], { uid: true });
    else await client.messageFlagsRemove(String(uid), [imapFlag], { uid: true });
  });
}

/** Move a message from one folder to another. */
export async function moveMessage(
  folder: string,
  uid: number,
  toFolder: string,
  mailboxAddress?: string,
): Promise<void> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  enforceRateLimit(`mail:move:${user.id}`, { max: 120, windowMs: 60 * 1000 });
  await withMailbox(cred, folder, async (client) => {
    await client.messageMove(String(uid), toFolder, { uid: true });
  });
}

/** Delete a message: move to Trash, or permanently expunge if already in Trash. */
export async function deleteMessage(folder: string, uid: number, mailboxAddress?: string): Promise<void> {
  const { user, cred } = await resolveMailbox(mailboxAddress);
  enforceRateLimit(`mail:delete:${user.id}`, { max: 120, windowMs: 60 * 1000 });

  await withImap(cred, async (client) => {
    // Determine the Trash folder path.
    let trashPath = "Trash";
    try {
      const list = await client.list();
      const trash = list.find((f) => folderRole(f.path, f.specialUse) === "trash");
      if (trash) trashPath = trash.path;
    } catch {
      /* fall back to "Trash" */
    }

    const inTrash = folderRole(folder) === "trash" || folder === trashPath;
    const lock = await client.getMailboxLock(folder);
    try {
      if (inTrash) {
        await client.messageDelete(String(uid), { uid: true });
      } else {
        await client.messageMove(String(uid), trashPath, { uid: true });
      }
    } finally {
      lock.release();
    }
  });
}

export function mailcowConfigured(): boolean {
  return Boolean(
    process.env.MAILCOW_API_URL?.trim() && process.env.MAILCOW_API_KEY?.trim(),
  );
}

function config(): { base: string; key: string } {
  const base = process.env.MAILCOW_API_URL?.trim();
  const key = process.env.MAILCOW_API_KEY?.trim();
  if (!base || !key) {
    throw new MailcowError(
      "Mailcow not configured — set MAILCOW_API_URL and MAILCOW_API_KEY.",
    );
  }
  return { base: base.replace(/\/+$/, ""), key };
}

/**
 * Core request helper. Performs a fetch to `${MAILCOW_API_URL}${path}` with the
 * X-API-Key header, parses the JSON body, and throws a MailcowError on any
 * non-2xx status or on a Mailcow error payload.
 */
async function mcRequest(
  method: "GET" | "POST",
  path: string,
  body?: unknown,
): Promise<unknown> {
  const { base, key } = config();
  const url = `${base}${path.startsWith("/") ? path : `/${path}`}`;

  let res: Response;
  try {
    res = await fetch(url, {
      method,
      headers: {
        "X-API-Key": key,
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: body === undefined ? undefined : JSON.stringify(body),
      cache: "no-store",
    });
  } catch (e) {
    throw new MailcowError(
      `Mailcow unreachable (${method} ${path}): ${e instanceof Error ? e.message : String(e)}`,
    );
  }

  const text = await res.text();
  let parsed: unknown = text;
  try {
    parsed = text ? JSON.parse(text) : null;
  } catch {
    // leave parsed as raw text
  }

  if (!res.ok) {
    throw new MailcowError(
      `Mailcow ${method} ${path} -> HTTP ${res.status}`,
      res.status,
      parsed,
    );
  }

  assertNoApiError(parsed, `${method} ${path}`);
  return parsed;
}

